        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "";
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@using sv_b6203c60387843218de7798ef26fd0fc.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge @BadgeClass">@AlertService.CurrentLowStockCount</span>

@code {
    /// <summary>
    /// When true, this instance subscribes to polling (controls the timer lifecycle).
    /// Sidebar badges set this to false — they display data but don't own the poll.
    /// The dashboard sets this to true so polling starts/stops with page visibility.
    /// </summary>
    [Parameter] public bool OwnsPolling { get; set; }

    private string BadgeClass => AlertService.CurrentLowStockCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertChanged;

        if (OwnsPolling)
        {
            AlertService.Subscribe();
        }
    }

    private void HandleAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertChanged;

        if (OwnsPolling)
        {
            AlertService.Unsubscribe();
        }
    }
}

