namespace sv_b6203c60387843218de7798ef26fd0fc.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and broadcasts results
/// to all subscribed components in the same circuit.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired whenever new alert data arrives. All subscribed components receive this.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component wants polling to be active. Polling runs as long as
    /// at least one subscriber is registered.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    /// <summary>
    /// Call when a component no longer needs polling (e.g., it's disposed).
    /// </summary>
    public void Unsubscribe()
    {
        _subscriberCount--;
        if (_subscriberCount <= 0)
        {
            _subscriberCount = 0;
            StopPolling();
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken cancellationToken)
    {
        // Fetch immediately on start
        await FetchAndNotifyAsync();

        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(cancellationToken))
                    break;

                await FetchAndNotifyAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertDataChanged?.Invoke();
    }

    private void HandleWarehouseChanged()
    {
        // When warehouse changes and polling is active, fetch immediately
        if (_subscriberCount > 0)
        {
            _ = FetchAndNotifyAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        StopPolling();
    }
}

